function canCreate(PDO $pdo,int $uid):bool{if(strcasecmp((string)($_SESSION['usuario_tipo']??''),'Administrador')===0)return true;$s=$pdo->prepare("SELECT u.is_community_user OR EXISTS(SELECT 1 FROM usuario_roles ur JOIN roles r ON r.id_role=ur.id_role WHERE ur.id_usuario=u.id_usuario AND r.slug IN('comunitario','administrador')) FROM usuario u WHERE u.id_usuario=?");$s->execute([$uid]);return (bool)$s->fetchColumn();}
