function uploadMedia(array $file,string $kind):array{if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return [null,null,null];if(($file['error']??1)!==UPLOAD_ERR_OK)respond(false,['message'=>'Falha no upload.'],422);$max=$kind==='sticker'?2*1024*1024:8*1024*1024;if(($file['size']??0)>$max)respond(false,['message'=>$kind==='sticker'?'Figurinha deve ter até 2 MB.':'Imagem deve ter até 8 MB.'],422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=$kind==='sticker'?['image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif']:['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(!isset($allowed[$mime]))respond(false,['message'=>'Formato de mídia não permitido.'],422);$dir=dirname(__DIR__,2).'/static/uploads/social';if(!is_dir($dir)&&!mkdir($dir,0775,true))respond(false,['message'=>'Armazenamento indisponível.'],500);$name=bin2hex(random_bytes(18)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))respond(false,['message'=>'Não foi possível salvar a mídia.'],500);return ['../static/uploads/social/'.$name,$mime,(int)$file['size']];}
function uploadPostMedia(array $file,bool $communityOnly=false):array{if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return [null,null];if(($file['error']??1)!==UPLOAD_ERR_OK)respond(false,['message'=>'Falha no envio da mídia.'],422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['image/jpeg'=>['jpg','imagem',8*1024*1024],'image/png'=>['png','imagem',8*1024*1024],'image/webp'=>['webp','imagem',8*1024*1024],'video/mp4'=>['mp4','video',40*1024*1024]];if(!$communityOnly){$allowed['image/gif']=['gif','imagem',8*1024*1024];$allowed['video/webm']=['webm','video',40*1024*1024];}if(!isset($allowed[$mime]))respond(false,['message'=>$communityOnly?'Use JPG, PNG, WebP ou MP4.':'Use JPG, PNG, WebP, GIF, MP4 ou WebM.'],422);[$ext,$type,$max]=$allowed[$mime];if(($file['size']??0)>$max)respond(false,['message'=>$type==='video'?'O vídeo deve ter até 40 MB.':'A imagem deve ter até 8 MB.'],422);$dir=dirname(__DIR__,2).'/static/uploads/social/feed';if(!is_dir($dir)&&!mkdir($dir,0775,true))respond(false,['message'=>'Armazenamento indisponível.'],500);$name=bin2hex(random_bytes(20)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))respond(false,['message'=>'Não foi possível salvar a mídia.'],500);return ['../static/uploads/social/feed/'.$name,$type];}
function isAdministrator():bool{return strcasecmp(trim((string)($_SESSION['usuario_tipo']??'')),'Administrador')===0;}
