function communityRole(PDO $pdo,int $community,int $uid):?string{$s=$pdo->prepare("SELECT papel FROM social_comunidade_membros WHERE id_comunidade=? AND id_usuario=? AND status='ativo' LIMIT 1");$s->execute([$community,$uid]);$role=$s->fetchColumn();return $role===false?null:(string)$role;}
function moderateCommunity(PDO $pdo,int $community,int $uid):string{$role=communityRole($pdo,$community,$uid);if(!in_array($role,['dono','moderador'],true))respond(false,['message'=>'Apenas o dono ou moderadores podem realizar esta ação.'],403);return $role;}
function readablePost(PDO $pdo,int $post,int $uid):array{$s=$pdo->prepare("SELECT p.id_post,p.id_comunidade,c.id_criador,m.status FROM social_posts p LEFT JOIN social_comunidades c ON c.id_comunidade=p.id_comunidade LEFT JOIN social_comunidade_membros m ON m.id_comunidade=p.id_comunidade AND m.id_usuario=? WHERE p.id_post=?");$s->execute([$uid,$post]);$row=$s->fetch();if(!$row)respond(false,['message'=>'Publicação não encontrada.'],404);if($row['id_comunidade']!==null&&($row['status']??'')!=='ativo'&&(int)($row['id_criador']??0)!==$uid&&!isAdministrator())respond(false,['message'=>'Entre na comunidade para interagir com esta publicação.'],403);return $row;}
