if($action==='overview'){$s=$pdo->prepare("SELECT c.*,u.nm_usuario criador,(SELECT COUNT(*) FROM social_comunidade_membros m WHERE m.id_comunidade=c.id_comunidade AND m.status='ativo') membros FROM social_comunidades c JOIN usuario u ON u.id_usuario=c.id_criador ORDER BY c.criado_em DESC LIMIT 30");$s->execute();$com=$s->fetchAll();$s=$pdo->prepare("SELECT c.*,COALESCE(l.nome,c.nome,(SELECT u2.nm_usuario FROM social_chat_membros om JOIN usuario u2 ON u2.id_usuario=om.id_usuario WHERE om.id_chat=c.id_chat AND om.id_usuario<>cm.id_usuario LIMIT 1)) titulo,(SELECT u2.foto_perfil FROM social_chat_membros om JOIN usuario u2 ON u2.id_usuario=om.id_usuario WHERE om.id_chat=c.id_chat AND om.id_usuario<>cm.id_usuario LIMIT 1) foto_perfil,(SELECT MAX(m.criado_em) FROM social_mensagens m WHERE m.id_chat=c.id_chat) ultima_mensagem FROM social_chats c JOIN social_chat_membros cm ON cm.id_chat=c.id_chat AND cm.id_usuario=? LEFT JOIN locais l ON l.id_local=c.id_local ORDER BY ultima_mensagem DESC,c.criado_em DESC");$s->execute([$uid]);respond(true,['communities'=>$com,'chats'=>$s->fetchAll(),'canCreateCommunity'=>canCreate($pdo,$uid)]);}
