if($action==='messages'){$chat=(int)($_GET['chat']??0);member($pdo,$chat,$uid);$after=(int)($_GET['after']??0);$fields="m.*,u.nm_usuario,u.foto_perfil,rm.texto resposta_texto,rm.tipo_anexo resposta_tipo_anexo,ru.nm_usuario resposta_autor";$joins=' JOIN usuario u ON u.id_usuario=m.id_usuario LEFT JOIN social_mensagens rm ON rm.id_mensagem=m.id_mensagem_resposta LEFT JOIN usuario ru ON ru.id_usuario=rm.id_usuario ';if($after>0){$s=$pdo->prepare("SELECT $fields FROM social_mensagens m $joins WHERE m.id_chat=? AND m.id_mensagem>? ORDER BY m.id_mensagem LIMIT 100");$s->execute([$chat,$after]);}else{$s=$pdo->prepare("SELECT recent.* FROM (SELECT $fields FROM social_mensagens m $joins WHERE m.id_chat=? ORDER BY m.id_mensagem DESC LIMIT 100) recent ORDER BY recent.id_mensagem");$s->execute([$chat]);}respond(true,['messages'=>$s->fetchAll()]);}
if($action==='send'){$d=$_POST;requireCsrf($d);$chat=(int)($d['chat']??0);member($pdo,$chat,$uid);$text=mb_substr(trim((string)($d['text']??'')),0,4000);$reply=(int)($d['reply_to']??0);if($reply>0){/* A resposta só pode citar uma mensagem do mesmo chat. */$parent=$pdo->prepare('SELECT id_mensagem FROM social_mensagens WHERE id_mensagem=? AND id_chat=?');$parent->execute([$reply,$chat]);if(!$parent->fetchColumn())respond(false,['message'=>'A mensagem respondida não está mais disponível.'],422);}else{$reply=null;}$kind=in_array(($d['kind']??''),['imagem','sticker'],true)?$d['kind']:'nenhum';[$url,$mime,$size]=uploadMedia($_FILES['media']??[],$kind==='sticker'?'sticker':'imagem');if($text===''&&!$url)respond(false,['message'=>'Digite uma mensagem ou envie uma mídia.'],422);$s=$pdo->prepare('INSERT INTO social_mensagens(id_chat,id_usuario,id_mensagem_resposta,texto,tipo_anexo,anexo_url,mime_type,tamanho_bytes) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$chat,$uid,$reply,$text,$url?$kind:'nenhum',$url,$mime,$size]);respond(true,['id'=>(int)$pdo->lastInsertId()]);}
if($action==='edit_message'){$d=input();requireCsrf($d);$message=(int)($d['message']??0);$text=mb_substr(trim((string)($d['text']??'')),0,4000);$s=$pdo->prepare('SELECT id_chat,anexo_url FROM social_mensagens WHERE id_mensagem=? AND id_usuario=?');$s->execute([$message,$uid]);$row=$s->fetch();if(!$row)respond(false,['message'=>'Mensagem não encontrada ou sem permissão para editar.'],404);member($pdo,(int)$row['id_chat'],$uid);if($text===''&&empty($row['anexo_url']))respond(false,['message'=>'O texto não pode ficar vazio.'],422);$pdo->prepare('UPDATE social_mensagens SET texto=?,editado_em=CURRENT_TIMESTAMP WHERE id_mensagem=? AND id_usuario=?')->execute([$text,$message,$uid]);respond(true,['text'=>$text,'message'=>'Mensagem atualizada.']);}
if($action==='community_members'){$id=(int)($_GET['community']??0);$role=moderateCommunity($pdo,$id,$uid);$s=$pdo->prepare("SELECT m.id_usuario,m.papel,m.status,m.entrou_em,u.nm_usuario,u.social_handle,u.foto_perfil FROM social_comunidade_membros m JOIN usuario u ON u.id_usuario=m.id_usuario WHERE m.id_comunidade=? ORDER BY FIELD(m.status,'pendente','ativo','bloqueado'),FIELD(m.papel,'dono','moderador','membro'),u.nm_usuario");$s->execute([$id]);respond(true,['members'=>$s->fetchAll(),'role'=>$role]);}
if($action==='update_community'){$d=$_POST;requireCsrf($d);$id=(int)($d['community']??0);$current=managedCommunity($pdo,$id,$uid);$name=trim((string)($d['name']??''));$description=trim((string)($d['description']??''));if(mb_strlen($name)<3||mb_strlen($description)<10)respond(false,['message'=>'Informe nome e descrição válidos.'],422);$image=communityImage($_FILES['image']??[]);$s=$pdo->prepare('UPDATE social_comunidades SET nome=?,descricao=?,privada=?,imagem_capa=COALESCE(?,imagem_capa) WHERE id_comunidade=?');$s->execute([$name,$description,!empty($d['private']),$image,$id]);if($image)removeStoredUpload((string)($current['imagem_capa']??''));respond(true,['message'=>'Comunidade atualizada.','image'=>$image?:$current['imagem_capa']]);}
if($action==='add_community_member'){$d=input();requireCsrf($d);$id=(int)($d['community']??0);managedCommunity($pdo,$id,$uid);$query=ltrim(trim((string)($d['handle']??'')),'@');if($query==='')respond(false,['message'=>'Informe o nome do usuário.'],422);$s=$pdo->prepare('SELECT id_usuario FROM usuario WHERE nm_usuario=? OR social_handle=? ORDER BY nm_usuario=? DESC LIMIT 1');$s->execute([$query,$query,$query]);$memberId=(int)$s->fetchColumn();if(!$memberId)respond(false,['message'=>'Usuário não encontrado.'],404);$pdo->prepare("INSERT INTO social_comunidade_membros(id_comunidade,id_usuario,papel,status) VALUES(?,?,'membro','ativo') ON DUPLICATE KEY UPDATE status='ativo'")->execute([$id,$memberId]);respond(true,['message'=>'Membro adicionado.']);}
if($action==='approve_community_member'){$d=input();requireCsrf($d);$id=(int)($d['community']??0);$memberId=(int)($d['user']??0);managedCommunity($pdo,$id,$uid);$s=$pdo->prepare("UPDATE social_comunidade_membros SET status='ativo' WHERE id_comunidade=? AND id_usuario=? AND papel<>'dono'");$s->execute([$id,$memberId]);if(!$s->rowCount())respond(false,['message'=>'Solicitação não encontrada.'],404);respond(true,['message'=>'Membro aprovado.']);}
if($action==='reject_community_member'){$d=input();requireCsrf($d);$id=(int)($d['community']??0);$memberId=(int)($d['user']??0);managedCommunity($pdo,$id,$uid);$s=$pdo->prepare("DELETE FROM social_comunidade_membros WHERE id_comunidade=? AND id_usuario=? AND status='pendente' AND papel<>'dono'");$s->execute([$id,$memberId]);if(!$s->rowCount())respond(false,['message'=>'Solicitação não encontrada ou já processada.'],404);respond(true,['message'=>'Solicitação recusada.']);}
if($action==='set_community_role'){$d=input();requireCsrf($d);$id=(int)($d['community']??0);$memberId=(int)($d['user']??0);$role=(string)($d['role']??'membro');$community=managedCommunity($pdo,$id,$uid);if(!in_array($role,['membro','moderador'],true))respond(false,['message'=>'Cargo inválido.'],422);if($memberId===(int)$community['id_criador'])respond(false,['message'=>'O cargo do dono não pode ser alterado.'],422);$s=$pdo->prepare("UPDATE social_comunidade_membros SET papel=? WHERE id_comunidade=? AND id_usuario=? AND status='ativo' AND papel<>'dono'");$s->execute([$role,$id,$memberId]);if(!$s->rowCount())respond(false,['message'=>'Membro não encontrado ou cargo já aplicado.'],404);respond(true,['message'=>$role==='moderador'?'Moderador definido.':'Cargo de moderador removido.']);}
if($action==='remove_community_member'){$d=input();requireCsrf($d);$id=(int)($d['community']??0);$memberId=(int)($d['user']??0);$role=moderateCommunity($pdo,$id,$uid);$target=$pdo->prepare('SELECT papel FROM social_comunidade_membros WHERE id_comunidade=? AND id_usuario=?');$target->execute([$id,$memberId]);$targetRole=$target->fetchColumn();if($targetRole===false)respond(false,['message'=>'Membro não encontrado.'],404);if($targetRole==='dono')respond(false,['message'=>'O dono não pode ser removido da comunidade.'],422);if($role==='moderador'&&$targetRole!=='membro')respond(false,['message'=>'Moderadores só podem expulsar membros comuns.'],403);$s=$pdo->prepare("DELETE FROM social_comunidade_membros WHERE id_comunidade=? AND id_usuario=? AND papel<>'dono'");$s->execute([$id,$memberId]);if(!$s->rowCount())respond(false,['message'=>'Membro não encontrado.'],404);respond(true,['message'=>'Membro expulso da comunidade.']);}
if($action==='places'){$s=$pdo->query("SELECT id_local,nome,tipo,descricao,logradouro,numero,bairro,cidade,uf,cep,latitude,longitude,imagem_principal,acessibilidades FROM locais WHERE status='aprovado' ORDER BY nome");respond(true,['places'=>$s->fetchAll()]);}
respond(false,['message'=>'Ação inválida.'],400);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());respond(false,['message'=>'Módulo Social indisponível. Execute a migração 20260912_social.sql.'],500);}
